scan_table_check.script:
(function(engine, current) {
    var messages = new global.EcsUpdateSet(current).outOfBoxChanges();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CFG-007',
        title: 'Update set changes an out-of-box record',
        recommendation: 'Avoid changing out-of-box records: extend them (for example a new Business Rule or Script Include) instead. If the change is needed, document it; the record is now skipped by upgrades and must be reviewed after every upgrade.',
        current: current
    });
    for (var i = 0; i < messages.length; i++) {
        report.addRecord(messages[i]);
    }
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
